    if (kind === 'plants' && isNew) { if (x.fromDrawing) { const key = x.fromDrawing; const p = C.seedPlant(key, { workspace: x.workspace, code: x.code || `DP-SITE-${Math.floor(Math.random() * 90 + 10)}`, read: C.nowStr(), depth: 'bare', live: false, people: [] }); p.name = x.name || p.name; p.capacity = x.capacity || p.capacity; C.audit(p.id, `Added ${p.name} from its drawing`, `${plural(C.of('unitProcesses', p.id).length, 'unit process', 'unit processes')} · ${plural(C.of('equipment', p.id).length, 'machine')} · ${plural(C.of('readings', p.id).length, 'reading')}`); C.persist(); closeDrawer(); go(`#/plant/${p.id}/overview`); toast(`<b>${esc(p.name)}</b> added from its drawing. Inherit what the library offers next.`); return; } delete x.fromDrawing; x.id = x.id || C.uid('pl'); CFG.add('plants', x); closeDrawer(); go(`#/plant/${x.id}/equipment`); toast(`<b>${esc(x.name)}</b> added. Add its unit processes and machines.`); return; }
    let members = null; if (kind === 'controlGroups') { members = x.members || []; delete x.members; }
    const was = isNew ? null : C.by(kind, x.id); const before = was ? C.clone(was) : null;
    if (isNew) { CFG.add(kind, x); } else { const patch = { ...x }; CFG.update(kind, x.id, patch); if (kind === 'alerts' || kind === 'schedules') { if (before && before.status !== x.status) C.audit(x.plantId, `${x.status === 'active' ? 'Activated' : x.status === 'off' ? 'Switched off' : 'Set to draft'} ${x.name}`, ''); } }
    if (members) { const moved = []; C.of('equipment').forEach((e) => { if (members.includes(e.id) && e.unitProcessId === x.unitProcessId) { if (e.controlGroupId !== x.id) { e.controlGroupId = x.id; moved.push(e.tag); } } else if (e.controlGroupId === x.id) { e.controlGroupId = null; moved.push(e.tag); } }); if (moved.length) C.audit(x.plantId, `Changed the members of ${x.name}`, moved.join(', ')); C.persist(); }
